CREATE OR REPLACE FUNCTION public.broker_can_review(_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.hercules_has_role(auth.uid(),'broker') AND EXISTS(SELECT 1 FROM public.company_members WHERE company_id=_company AND user_id=auth.uid() AND status='active') $$;
REVOKE ALL ON FUNCTION public.broker_can_review(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.broker_can_review(uuid) TO authenticated,service_role;
CREATE TABLE public.broker_inbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), provider text NOT NULL, external_id text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','processed','failed')), attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,provider,external_id));
GRANT SELECT ON public.broker_inbox_events TO authenticated; GRANT ALL ON public.broker_inbox_events TO service_role;
ALTER TABLE public.broker_inbox_events ENABLE ROW LEVEL SECURITY; CREATE POLICY broker_inbox_read ON public.broker_inbox_events FOR SELECT TO authenticated USING(public.broker_can_review(company_id));
CREATE TABLE public.broker_intake_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), event_id uuid UNIQUE REFERENCES public.broker_inbox_events(id), reference text NOT NULL CHECK(length(btrim(reference)) BETWEEN 1 AND 120), origin text NOT NULL DEFAULT '', destination text NOT NULL DEFAULT '', email_subject text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'load_offer' CHECK(category IN ('load_offer','bol_packet','exception','other')), urgent boolean NOT NULL DEFAULT false, notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'needs_review' CHECK(status IN ('needs_review','approved','rejected')), selected_carrier_id uuid, created_by uuid NOT NULL, approved_by uuid, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,id), FOREIGN KEY(company_id,selected_carrier_id) REFERENCES public.freight_carriers(company_id,id));
GRANT SELECT ON public.broker_intake_drafts TO authenticated; GRANT ALL ON public.broker_intake_drafts TO service_role;
ALTER TABLE public.broker_intake_drafts ENABLE ROW LEVEL SECURITY; CREATE POLICY broker_draft_read ON public.broker_intake_drafts FOR SELECT TO authenticated USING(public.broker_can_review(company_id));
CREATE TABLE public.broker_delivery_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL, draft_id uuid NOT NULL UNIQUE, carrier_id uuid NOT NULL, approved_by uuid NOT NULL, approved_at timestamptz NOT NULL DEFAULT now(), recipient_email text NOT NULL, packet jsonb NOT NULL, status text NOT NULL DEFAULT 'needs_connection' CHECK(status IN ('needs_connection','pending','processing','sent','delivered','failed')), attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz, provider_message_id text, last_error text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(company_id,draft_id) REFERENCES public.broker_intake_drafts(company_id,id), FOREIGN KEY(company_id,carrier_id) REFERENCES public.freight_carriers(company_id,id));
GRANT SELECT ON public.broker_delivery_outbox TO authenticated; GRANT ALL ON public.broker_delivery_outbox TO service_role;
ALTER TABLE public.broker_delivery_outbox ENABLE ROW LEVEL SECURITY; CREATE POLICY broker_outbox_read ON public.broker_delivery_outbox FOR SELECT TO authenticated USING(public.broker_can_review(company_id));
CREATE TABLE public.broker_review_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL, draft_id uuid NOT NULL, actor_id uuid NOT NULL, action text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(company_id,draft_id) REFERENCES public.broker_intake_drafts(company_id,id));
GRANT SELECT ON public.broker_review_history TO authenticated; GRANT ALL ON public.broker_review_history TO service_role;
ALTER TABLE public.broker_review_history ENABLE ROW LEVEL SECURITY; CREATE POLICY broker_history_read ON public.broker_review_history FOR SELECT TO authenticated USING(public.broker_can_review(company_id));
ALTER TABLE public.freight_carriers ADD COLUMN recipient_verified_at timestamptz;
ALTER TABLE public.freight_carriers ADD COLUMN recipient_verified_email text;
COMMENT ON COLUMN public.freight_carriers.recipient_verified_email IS 'Trusted provider/admin verification only; must match current contact_email before broker packet approval. No browser writes.';
CREATE OR REPLACE FUNCTION public.broker_intake_create(_company uuid,_reference text,_origin text,_destination text,_subject text,_category text,_urgent boolean,_notes text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d uuid; BEGIN IF NOT public.broker_can_review(_company) THEN RAISE EXCEPTION 'Broker company access required'; END IF; INSERT INTO public.broker_intake_drafts(company_id,reference,origin,destination,email_subject,category,urgent,notes,created_by) VALUES(_company,btrim(_reference),btrim(_origin),btrim(_destination),_subject,_category,_urgent,_notes,auth.uid()) RETURNING id INTO d; INSERT INTO public.broker_review_history(company_id,draft_id,actor_id,action) VALUES(_company,d,auth.uid(),'created_manual_draft'); RETURN d; END $$;
REVOKE ALL ON FUNCTION public.broker_intake_create(uuid,text,text,text,text,text,boolean,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.broker_intake_create(uuid,text,text,text,text,text,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.broker_intake_approve(_draft uuid,_carrier uuid,_document uuid,_confirmed boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.broker_intake_drafts; c public.freight_carriers; doc public.documents; job uuid; BEGIN IF _confirmed IS NOT TRUE THEN RAISE EXCEPTION 'Explicit confirmation required'; END IF; SELECT * INTO d FROM public.broker_intake_drafts WHERE id=_draft FOR UPDATE; IF d.id IS NULL OR NOT public.broker_can_review(d.company_id) THEN RAISE EXCEPTION 'Broker company access required'; END IF; SELECT id INTO job FROM public.broker_delivery_outbox WHERE draft_id=d.id; IF job IS NOT NULL THEN IF EXISTS(SELECT 1 FROM public.broker_delivery_outbox WHERE id=job AND carrier_id=_carrier AND packet->>'document_id'=_document::text AND approved_by=auth.uid()) THEN RETURN job; END IF; RAISE EXCEPTION 'Approved packet differs; duplicate refused'; END IF; IF d.status<>'needs_review' OR btrim(d.origin)='' OR btrim(d.destination)='' THEN RAISE EXCEPTION 'Load requires complete lane and pending review'; END IF; SELECT * INTO c FROM public.freight_carriers WHERE id=_carrier AND company_id=d.company_id FOR SHARE; IF c.id IS NULL OR c.verification_status<>'verified' OR c.insurance_expires IS NULL OR c.insurance_expires<CURRENT_DATE OR c.recipient_verified_at IS NULL OR lower(c.recipient_verified_email) IS DISTINCT FROM lower(c.contact_email) OR c.contact_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Carrier and recipient must be verified with current insurance'; END IF; SELECT * INTO doc FROM public.documents WHERE id=_document AND owner_id=auth.uid() FOR SHARE; IF doc.id IS NULL OR doc.kind<>'bol' OR doc.status NOT IN ('ready','finalized','approved') OR doc.storage_path IS NULL OR doc.load_reference IS DISTINCT FROM d.reference THEN RAISE EXCEPTION 'Owned finalized BOL file matching load reference required'; END IF; UPDATE public.broker_intake_drafts SET status='approved',selected_carrier_id=c.id,approved_by=auth.uid(),approved_at=now() WHERE id=d.id; INSERT INTO public.broker_delivery_outbox(company_id,draft_id,carrier_id,approved_by,recipient_email,packet) VALUES(d.company_id,d.id,c.id,auth.uid(),c.contact_email,jsonb_build_object('reference',d.reference,'origin',d.origin,'destination',d.destination,'document_id',doc.id,'document_updated_at',doc.updated_at,'storage_path',doc.storage_path,'carrier_name',c.name)) RETURNING id INTO job; INSERT INTO public.broker_review_history(company_id,draft_id,actor_id,action,detail) VALUES(d.company_id,d.id,auth.uid(),'approved_packet',jsonb_build_object('carrier_id',c.id,'outbox_id',job,'delivery','needs_connection')); RETURN job; END $$;
REVOKE ALL ON FUNCTION public.broker_intake_approve(uuid,uuid,uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.broker_intake_approve(uuid,uuid,uuid,boolean) TO authenticated;
CREATE INDEX broker_inbox_retry ON public.broker_inbox_events(status,next_attempt_at); CREATE INDEX broker_outbox_retry ON public.broker_delivery_outbox(status,next_attempt_at);
COMMENT ON TABLE public.broker_delivery_outbox IS 'Persistent approved packet intents. No sender or scheduler connected: needs_connection is not sent or delivered. Trusted worker must revalidate recipient and document snapshot before dispatch.';
COMMENT ON TABLE public.broker_inbox_events IS 'Durable provider event staging with tenant-scoped idempotency; no provider webhook activated in this slice.';